import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterModule } from '@angular/router';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';

// --- INTERFACES OFFICIELLES ---
export interface Reclamation {
  id: number;
  reference: string;
  statut: 'OUVERTE' | 'EN_COURS_IA' | 'RESOLUE_PAR_IA' | 'ESCALADEE_SUPPORT' | 'CLOTUREE';
  priorite: 'BASSE' | 'NORMALE' | 'HAUTE';
  description: string;
  categorieCode: string;
  categorieLibelle: string;
  sousCategorieCode: string;
  sousCategorieLibelle: string;
  dateCreation: string;
  dateMiseAJour: string;
}

export interface Page<T> {
  content: T[];
  totalElements: number;
  totalPages: number;
  size: number;
  number: number;
}

// Remplacez par votre URL d'API réelle
const API_URL = 'http://localhost:8080/api';
@Component({
  selector: 'app-zone',
  templateUrl: './zone.component.html',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterModule],
  styleUrls: ['./zone.component.css']
})
export class ZoneComponent {

private http = inject(HttpClient);
  private router = inject(Router);

  private readonly url = `${API_URL}/reclamations`;

  // Données
  reclamations: Reclamation[] = [];
  loading: boolean = false;
  errorMessage: string = '';

  // Filtres & Pagination
  searchTerm: string = '';
  selectedStatus: string = 'TOUS';
  page: number = 0;
  size: number = 10;
  totalPages: number = 0;

  ngOnInit(): void {
    this.chargerReclamations();
  }

  /** GET /api/reclamations?page=0&size=10 */
  chargerReclamations(): void {
    this.loading = true;
    const params = new HttpParams().set('page', this.page).set('size', this.size);

    this.http.get<Page<Reclamation>>(this.url, { params }).subscribe({
      next: (data) => {
        this.reclamations = data.content || [];
        this.totalPages = data.totalPages || 0;
        this.loading = false;
      },
      error: (err) => {
        console.error('Erreur lors du chargement des réclamations', err);
        this.errorMessage = 'Impossible de charger les réclamations depuis le serveur.';
        this.loading = false;
      }
    });
  }

  /** POST /api/reclamations/{id}/escalade */
  escaladerTicket(id: number): void {
    const motif = prompt('Motif de l\'escalade (optionnel) :');
    this.http.post<Reclamation>(`${this.url}/${id}/escalade`, motif ? { motif } : null).subscribe({
      next: (updated) => {
        const index = this.reclamations.findIndex(r => r.id === id);
        if (index !== -1) {
          this.reclamations[index] = updated;
        }
      },
      error: (err) => alert('Erreur lors de l\'escalade du ticket.')
    });
  }

  get filteredReclamations(): Reclamation[] {
    return this.reclamations.filter(rec => {
      const matchesSearch = 
        rec.reference.toLowerCase().includes(this.searchTerm.toLowerCase()) ||
        rec.description.toLowerCase().includes(this.searchTerm.toLowerCase()) ||
        rec.sousCategorieLibelle.toLowerCase().includes(this.searchTerm.toLowerCase());

      const matchesStatus = 
        this.selectedStatus === 'TOUS' || 
        rec.statut === this.selectedStatus;

      return matchesSearch && matchesStatus;
    });
  }
}
